subtopics.example:
console.log(count); // undefined, not an error
var count = 5;
console.log(count); // 5

hi(); // works
function hi() { console.log('hi'); }
bye(); // TypeError / ReferenceError
const bye = () => console.log('bye');

// Declare-before-use keeps hoisting from ever surprising you
const MAX = 100;
function clamp(n) { return Math.min(n, MAX); }

sandbox.code:
console.log(a); // undefined — var is hoisted and initialized
var a = 1;

try {
  console.log(b); // throws — b is in the TDZ
  let b = 2;
} catch (e) {
  console.log(e.constructor.name); // 'ReferenceError'
}

console.log(declared()); // 'I am declared' — fully hoisted

function declared() {
  return 'I am declared';
}

try {
  console.log(expressed()); // throws — only the const binding is hoisted (TDZ)
  const expressed = () => 'I am expressed';
} catch (e) {
  console.log(e.constructor.name); // 'ReferenceError'
}

function getStatus() {
  const snapshot = status; // reads BEFORE assignment
  var status = 'ready';
  return snapshot; // currently undefined
}

console.log(getStatus()); // want 'ready'

solution.code:
function getStatus() {
  const status = 'ready'; // declare before use
  const snapshot = status;
  return snapshot;
}

console.log(getStatus()); // 'ready'

brokenCode.code:
const total = 100;

function render() {
  console.log(total); // intended to read the outer 100
  let total = 50;     // but this declares a new local total
  return total;
}

render(); // throws ReferenceError

solution.code:
const total = 100;

function render() {
  const outer = total; // read the outer value first
  const localTotal = 50; // rename to avoid shadowing
  console.log(outer);    // 100
  return localTotal;
}

render();

// Original logs: undefined
// var x;            // hoisted as undefined
// function foo(){ console.log(x); }
// foo();            // undefined
// x = 5;

// Hoisting-safe rewrite:
const x = 5;
function foo() { console.log(x); }
foo(); // 5
